class Tags extends Array {
  static get [Symbol.species]() {
    return Array;
  }

  get [Symbol.toStringTag]() {
    return "Tags";
  }
}

const tags = Tags.from(["js", "css"]);
const short = tags.filter((tag) => tag.length < 3);
const tagOf = (value) => Object.prototype.toString.call(value);

console.log(tagOf(tags));
console.log(tagOf(short));
console.log(short instanceof Tags);
console.log([0].concat(tags).length);
